From aad8b007a7892e36110ffddebf9d7b823202f4b9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:47:22 +0100
Subject: [PATCH] applets/notifications: animate notifications away on Clear
 All

Clearing all notifications closed the popup right away, so it wasn't
clear that anything had happened. When everything is going to be
cleared, the notifications now slide out from the top before closing.

BUG: 445926
---
 applets/notifications/FullRepresentation.qml | 72 ++++++++++++++++++++
 applets/notifications/main.qml               |  8 +++
 2 files changed, 80 insertions(+)

diff --git a/applets/notifications/FullRepresentation.qml b/applets/notifications/FullRepresentation.qml
index ce873eca4d..90a0ef2c72 100644
--- a/applets/notifications/FullRepresentation.qml
+++ b/applets/notifications/FullRepresentation.qml
@@ -257,6 +257,32 @@ PlasmaExtras.Representation {
         }
     }

+    function animateClearHistory(clear: var): void {
+        if (list.clearing) {
+            return;
+        }
+        list.clearing = true;
+        clearHistoryTimer.clear = clear;
+        clearHistoryTimer.start();
+    }
+
+    Timer {
+        id: clearHistoryTimer
+        property var clear
+        interval: Kirigami.Units.longDuration * 2
+        onTriggered: {
+            clear();
+            // clear is async, keep the notifications hidden until they are gone
+            clearingResetTimer.start();
+        }
+    }
+
+    Timer {
+        id: clearingResetTimer
+        interval: 1000
+        onTriggered: list.clearing = false
+    }
+
     PlasmaComponents3.ScrollView {
         id: scrollView
         anchors.fill: parent
@@ -270,6 +296,8 @@ PlasmaExtras.Representation {
             model: fullRepresentationRoot.appletInterface.expanded ? fullRepresentationRoot.historyModel : null
             currentIndex: -1

+            property bool clearing: false
+
             topMargin: Kirigami.Units.largeSpacing
             bottomMargin: Kirigami.Units.largeSpacing
             spacing: Kirigami.Units.smallSpacing
@@ -349,6 +377,13 @@ PlasmaExtras.Representation {
                     width: list.width
                     // Within a section delegate we don't have other ways to detect whether we are the first section
                     height: y > 0 ? Math.round(Kirigami.Units.smallSpacing * 2) : 0
+                    opacity: list.clearing ? 0 : 1
+
+                    Behavior on opacity {
+                        NumberAnimation {
+                            duration: Kirigami.Units.longDuration
+                        }
+                    }

                     KSvg.SvgItem {
                         anchors {
@@ -458,6 +493,43 @@ PlasmaExtras.Representation {
                     }
                 }

+                Connections {
+                    target: list
+                    function onClearingChanged(): void {
+                        if (list.clearing) {
+                            clearAnim.restart();
+                        } else {
+                            clearAnim.stop();
+                            transl.x = 0;
+                            delegate.opacity = 1;
+                        }
+                    }
+                }
+
+                // Slide out one after the other from the top when clearing all notifications
+                SequentialAnimation {
+                    id: clearAnim
+                    PauseAnimation {
+                        duration: Math.max(0, Math.min(1, (delegate.y - list.contentY) / list.height)) * Kirigami.Units.longDuration
+                    }
+                    ParallelAnimation {
+                        NumberAnimation {
+                            target: transl
+                            property: "x"
+                            to: delegate.mirrored ? -delegate.width : delegate.width
+                            duration: Kirigami.Units.longDuration
+                            easing.type: Easing.InQuad
+                        }
+                        NumberAnimation {
+                            target: delegate
+                            property: "opacity"
+                            to: 0
+                            duration: Kirigami.Units.longDuration
+                            easing.type: Easing.InQuad
+                        }
+                    }
+                }
+
                 draggable: !delegate.isGroup && delegate.type != NotificationManager.Notifications.JobType

                 onDismissRequested: fullRepresentationRoot.historyModel.close(fullRepresentationRoot.historyModel.index(index, 0));
diff --git a/applets/notifications/main.qml b/applets/notifications/main.qml
index 8d98753eca..a4349545dc 100644
--- a/applets/notifications/main.qml
+++ b/applets/notifications/main.qml
@@ -249,6 +249,14 @@ PlasmoidItem {
             icon.name: "edit-clear-history"
             visible: historyModel.expiredNotificationsCount > 0
             onTriggered: {
+                // The popup closes once everything is cleared, so let the notifications visibly go away first
+                if (root.expanded && root.fullRepresentationItem && historyModel.activeNotificationsCount === 0) {
+                    root.fullRepresentationItem.animateClearHistory(clear);
+                } else {
+                    clear();
+                }
+            }
+            function clear() {
                 historyModel.clear(NotificationManager.Notifications.ClearExpired);
                 // clear is async,
                 historyModel.countChanged.connect(closeWhenCleared)
-- 
